-- Hosbah: a server's metrics history. The agent's heartbeats (every ~15 s) fold into one row per
-- minute (step 60: at is the minute, samples how many beats it averages). The retention job
-- (internal/metrics) folds minute rows older than 24 h into 15-minute rows (step 900) and drops
-- 15-minute rows older than 30 days, so a server holds at most ~1440 + ~2880 rows. net_rx/net_tx
-- are bytes per second; gpu is [{index, util, mem_used, mem_total, temp}] (NVIDIA only).
-- Rows go with their server (and so with their team).
ALTER TABLE server_metrics ADD CONSTRAINT server_metrics_step_check CHECK (step IN (60, 900));
CREATE UNIQUE INDEX server_metrics_bucket_key ON server_metrics (server_id, step, at);
CREATE INDEX server_metrics_team_at_idx ON server_metrics (team_id, at);
CREATE INDEX server_metrics_step_at_idx ON server_metrics (step, at);
